from pathlib import Path

app_path=Path('app.js')
css_path=Path('app.css')
index_path=Path('index.html')
app=app_path.read_text()
css=css_path.read_text()
index=index_path.read_text()

def rep(old,new,count=1):
    global app
    if old not in app:
        raise SystemExit('missing app marker: '+old[:120])
    app=app.replace(old,new,count)

old="const monsterAsset=f=>`monster-${f==='goblin'?'goblin':f==='troll'?'troll':'slime'}`;"
new=old+"\nconst evolutionDefForForm=form=>(S?.evolutionDefs||[]).find(x=>x.target_form_id===form)||null;\nconst formName=m=>{if(!m)return '몬스터';if(!Number(m.evolution_tier||0))return fam(m.family);return evolutionDefForForm(m.form_id)?.target_name||fam(m.family)};\nconst formClass=m=>`form-${String(m?.form_id||m?.family||'base').replace(/[^a-z0-9_-]/gi,'')}`;\nconst skillDef=m=>(S?.skillDefs||[]).find(x=>x.id===m?.skill_id)||null;\nconst branchesFor=m=>(S?.evolutionDefs||[]).filter(x=>x.base_family===m?.family&&x.from_form_id===(m?.form_id||m?.family));\nconst readyBranches=m=>branchesFor(m).filter(x=>Number(m?.level||0)>=Number(x.required_level||999));\nconst skillTriggerText=s=>{if(!s)return '';if(s.trigger_type==='every_n')return `${s.trigger_count}번째 공격마다 발동`;if(s.trigger_type==='hp_below_chance')return `아군 HP ${Math.round(Number(s.condition_value||0)*100)}% 이하 · 공격 시 ${Math.round(Number(s.trigger_value||0)*100)}% 확률`;return `공격 시 ${Math.round(Number(s.trigger_value||0)*100)}% 확률`};\nconst evoPct=v=>{const n=Math.round((Number(v||1)-1)*100);return `${n>=0?'+':''}${n}%`};"
rep(old,new)

