new="""function employeeModal(id){const m=S.monsters.find(x=>x.id===id);if(!m)return;const e=activeOf(m.id),site=e&&S.sites.find(x=>x.id===e.site_id),st=monsterStats(m),eq=equippedFor(m.id),sk=skillDef(m),branches=branchesFor(m),ready=readyBranches(m);const gear=['weapon','armor','accessory'].map(slot=>{const row=eq.find(x=>x.slot===slot),d=row&&itemDef(row.item_id);return `<div class=\"gear-slot ${d?rarityClass(d.rarity):'empty'}\"><small>${slotName(slot)}</small>${d?`<b>${itemSvg(itemAsset(d.id))}${esc(d.id)}</b><button data-action=\"unequip\" data-id=\"${m.id}\" data-slot=\"${slot}\">해제</button>`:`<b>비어 있음</b><span>창고 장비를 선택해 장착</span>`}</div>`}).join('');const evo=branches.length?`<section class=\"evolution-status ${ready.length?'ready':''}\"><div><small>${Number(m.evolution_tier||0)+1}차 전직</small><b>${ready.length?`전직 가능 · ${ready.length}개 분기`:`Lv.${branches[0].required_level} 필요 · 현재 Lv.${m.level}`}</b><span>${ready.length?'전직 후 Lv.1부터 새로운 성장 시작':`앞으로 ${Math.max(0,Number(branches[0].required_level)-Number(m.level||0))}레벨`}</span></div><button class=\"primary-btn\" data-action=\"evolution\" data-id=\"${m.id}\" ${!ready.length||e?'disabled':''}>${e?'전투 중':ready.length?'전직 선택':'레벨 부족'}</button></section>`:`<section class=\"evolution-status final\"><div><small>EVOLUTION</small><b>현재 최종 진화체</b><span>추가 전직 경로는 아직 없습니다.</span></div></section>`;modal(`<div class=\"sheet-head\"><div><div class=\"section-kicker\">MONSTER FILE · ${Number(m.evolution_tier||0)?`EVOLUTION ${m.evolution_tier}`:'BASE'} </div><h2>${esc(m.name)}</h2><p>${esc(formName(m))} · ${Number(m.evolution_tier||0)?`${m.evolution_tier}차 전직` : roleOf(m)} · 성장 ${esc(m.growth_grade||'C')}</p></div><button class=\"close-btn\" data-action=\"close\">×</button></div><div class=\"monster-profile-v10\"><div class=\"monster-identity\"><div class=\"detail-portrait\">${charSvg(monsterAsset(m.family),'detail-sprite '+formClass(m))}</div><div><button class=\"personality-tag\" data-action=\"personality\" data-id=\"${m.id}\">${esc(m.personality||'침착')}<i>?</i></button><b>${esc(m.trait||'무특성')}</b><small>Lv.${m.level} · 재능 ${fmt(m.talent)} · 누적 박멸 ${fmt(m.kills)}</small></div></div><div class=\"combat-stat-grid\"><div><small>HP</small><b>${fmt(st.hp)}</b></div><div><small>공격</small><b>${fmt(st.atk)}</b></div><div><small>방어</small><b>${fmt(st.def)}</b></div><div><small>속도</small><b>${fmt(st.spd)}</b></div><div><small>치명</small><b>${Math.round(st.crit*100)}%</b></div><div><small>회피</small><b>${Math.round(st.evade*100)}%</b></div></div>${sk?`<section class=\"unique-skill-card\"><div class=\"skill-gem\">S</div><div><small>고유 스킬</small><b>${esc(sk.name)}</b><strong>${esc(skillTriggerText(sk))}</strong><p>${esc(sk.description||'')}</p></div></section>`:`<section class=\"unique-skill-card locked\"><div class=\"skill-gem\">?</div><div><small>고유 스킬</small><b>전직 후 해금</b><p>Lv.20에 첫 전직을 완료하면 고유 스킬이 생깁니다.</p></div></section>`}${evo}<div class=\"gear-grid\">${gear}</div><div class=\"detail-note compact\"><b>${e?'현장 근무 중':'본부 대기'}</b><br>${e?`${esc(site?.name||'현장')} · 현재 ${esc(e.phase||'탐색')} 단계`:'박멸 화면에서 원하는 던전에 배치할 수 있습니다.'}</div></div>${e?`<div class=\"battle-actions\"><button class=\"primary-btn\" data-action=\"watch\" data-id=\"${e.id}\">현장 보기</button></div>`:''}`,'monster-detail-sheet-v10 evolution-enabled')}\n\nfunction evolutionModal(id){const m=S.monsters.find(x=>x.id===id);if(!m)return;if(activeOf(m.id)){toast('전투 중에는 전직할 수 없습니다.');return}const branches=branchesFor(m),ready=readyBranches(m);if(!branches.length){toast('현재 최종 진화체입니다.');return}modal(`<div class=\"sheet-head evolution-head\"><div><div class=\"section-kicker\">EVOLUTION BRANCH</div><h2>${esc(m.name)} 전직 선택</h2><p>${esc(formName(m))} Lv.${m.level} → 선택한 진화체 Lv.1</p></div><button class=\"close-btn\" data-action=\"close\">×</button></div><div class=\"evolution-warning\">전직하면 현재 레벨과 XP는 초기화됩니다. 이름·재능·성격·특성·장비·누적 박멸 기록은 유지됩니다.</div><div class=\"evolution-choice-list\">${branches.map(x=>{const sk=(S.skillDefs||[]).find(s=>s.id===x.skill_id),ok=Number(m.level)>=Number(x.required_level);return `<article class=\"evolution-choice ${ok?'ready':'locked'}\"><div class=\"evolution-preview ${formClass({form_id:x.target_form_id,family:m.family})}\">${charSvg(monsterAsset(m.family),'evolution-sprite '+formClass({form_id:x.target_form_id,family:m.family}))}<em>${x.tier}차</em></div><div class=\"evolution-copy\"><header><b>${esc(x.target_name)}</b><span>Lv.${x.required_level}</span></header><p>${esc(x.description||'')}</p><div class=\"evo-stats\"><span>HP ${evoPct(x.hp_mult)}</span><span>공격 ${evoPct(x.atk_mult)}</span><span>방어 ${evoPct(x.def_mult)}</span><span>속도 ${evoPct(x.spd_mult)}</span></div><div class=\"evo-skill\"><small>고유 스킬</small><b>${esc(sk?.name||'-')}</b><strong>${esc(skillTriggerText(sk))}</strong><p>${esc(sk?.description||'')}</p></div></div><button class=\"primary-btn evolve-select\" data-action=\"evolve-choice\" data-id=\"${m.id}\" data-evolution=\"${x.id}\" ${ok?'':'disabled'}>${ok?'이 경로로 전직':`Lv.${x.required_level} 필요`}</button></article>`}).join('')}</div>`,'evolution-sheet')}"""
